// Check if point q lies on segment pr (collinear and within bounds)
int onSegment(Point p, Point q, Point r) {
    if (q.x <= fmax(p.x, r.x) && q.x >= fmin(p.x, r.x) &&
        q.y <= fmax(p.y, r.y) && q.y >= fmin(p.y, r.y))
        return 1;
    return 0;
}

// Orientation of triplet (p, q, r)
double orientation(Point p, Point q, Point r) {
    double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (fabs(val) < 1e-9) return 0; // collinear
    return (val > 0) ? 1 : 2; // 1 clockwise, 2 counterclockwise
}

// Find intersection point of two lines (assuming not parallel)
Point lineIntersection(Point a1, Point a2, Point b1, Point b2) {
    double A1 = a2.y - a1.y;
    double B1 = a1.x - a2.x;
    double C1 = A1 * a1.x + B1 * a1.y;

    double A2 = b2.y - b1.y;
    double B2 = b1.x - b2.x;
    double C2 = A2 * b1.x + B2 * b1.y;

    double det = A1 * B2 - A2 * B1;
    Point p = { (B2 * C1 - B1 * C2) / det, (A1 * C2 - A2 * C1) / det };
    return p;
}

// Check if two segments intersect and get the intersection point
int segmentsIntersect(Segment s1, Segment s2, Point *inter) {
    Point p1 = s1.p1, q1 = s1.p2;
    Point p2 = s2.p1, q2 = s2.p2;

    double o1 = orientation(p1, q1, p2);
    double o2 = orientation(p1, q1, q2);
    double o3 = orientation(p2, q2, p1);
    double o4 = orientation(p2, q2, q1);

    // General case
    if (o1 != o2 && o3 != o4) {
        *inter = lineIntersection(p1, q1, p2, q2);
        return 1;
    }
    // Collinear cases
    if (o1 == 0 && onSegment(p1, p2, q1)) { *inter = p2; return 1; }
    if (o2 == 0 && onSegment(p1, q2, q1)) { *inter = q2; return 1; }
    if (o3 == 0 && onSegment(p2, p1, q2)) { *inter = p1; return 1; }
    if (o4 == 0 && onSegment(p2, q1, q2)) { *inter = q1; return 1; }

    return 0;
}

double triangleArea(Point a, Point b, Point c) {
    return fabs((a.x*(b.y-c.y) + b.x*(c.y-a.y) + c.x*(a.y-b.y)) / 2.0);
}

int isSamePoint(Point a, Point b) {
    return fabs(a.x - b.x) < 1e-9 && fabs(a.y - b.y) < 1e-9;
