static const double EPS = 1e-10;

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

int on_segment(Point a, Point b, Point p) {
    if (fabs(cross(a, b, p)) > EPS) return 0;
    double minx = a.x < b.x ? a.x : b.x;
    double maxx = a.x > b.x ? a.x : b.x;
    double miny = a.y < b.y ? a.y : b.y;
    double maxy = a.y > b.y ? a.y : b.y;
    return p.x >= minx - EPS && p.x <= maxx + EPS &&
           p.y >= miny - EPS && p.y <= maxy + EPS;
}

int line_intersection(Segment s1, Segment s2, Point *res) {
    double x1 = s1.a.x, y1 = s1.a.y, x2 = s1.b.x, y2 = s1.b.y;
    double x3 = s2.a.x, y3 = s2.a.y, x4 = s2.b.x, y4 = s2.b.y;

    double d = (x2 - x1) * (y4 - y3) - (y2 - y1) * (x4 - x3);
    if (fabs(d) < EPS) return 0; /* parallel or same line */

    double t = ((x3 - x1) * (y4 - y3) - (y3 - y1) * (x4 - x3)) / d;
    res->x = x1 + t * (x2 - x1);
    res->y = y1 + t * (y2 - y1);
    return 1;
}

int segment_intersection_point(Segment s1, Segment s2, Point *res) {
    if (!line_intersection(s1, s2, res)) return 0;
    return on_segment(s1.a, s1.b, *res) && on_segment(s2.a, s2.b, *res);
}

double triangle_area(Point p1, Point p2, Point p3) {
    double v = fabs(
        p1.x * (p2.y - p3.y) +
        p2.x * (p3.y - p1.y) +
        p3.x * (p1.y - p2.y)
    );
    return v / 2.0;
}

