struct Point {
    double x, y;
};

static const double EPS = 1e-9;

double cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

bool onSegment(const Point& a, const Point& b, const Point& p) {
    return fabs(cross(a, b, p)) < EPS &&
           min(a.x, b.x) - EPS <= p.x && p.x <= max(a.x, b.x) + EPS &&
           min(a.y, b.y) - EPS <= p.y && p.y <= max(a.y, b.y) + EPS;
}

bool segmentIntersectionPoint(const Point& a, const Point& b,
                              const Point& c, const Point& d,
                              Point& out) {
    double A1 = b.y - a.y;
    double B1 = a.x - b.x;
    double C1 = A1 * a.x + B1 * a.y;

    double A2 = d.y - c.y;
    double B2 = c.x - d.x;
    double C2 = A2 * c.x + B2 * c.y;

    double det = A1 * B2 - A2 * B1;
    if (fabs(det) < EPS) return false; // parallel or coincident -> not a unique point

    out.x = (B2 * C1 - B1 * C2) / det;
    out.y = (A1 * C2 - A2 * C1) / det;

    return onSegment(a, b, out) && onSegment(c, d, out);
}

