                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }
    }

    static final double EPS = 1e-10;

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static double cross(double ax, double ay, double bx, double by) {
        return ax * by - ay * bx;
    }

    static boolean inRange(double a, double b, double x) {
        return x >= Math.min(a, b) - EPS && x <= Math.max(a, b) + EPS;
    }

    static Point segmentIntersection(Point a, Point b, Point c, Point d) {
        double rX = b.x - a.x, rY = b.y - a.y;
        double sX = d.x - c.x, sY = d.y - c.y;

        double denom = cross(rX, rY, sX, sY);
        double qpx = c.x - a.x, qpy = c.y - a.y;

        if (Math.abs(denom) < EPS) {
            return null; // parallel or collinear -> not a unique intersection point
        }

        double t = cross(qpx, qpy, sX, sY) / denom;
        double u = cross(qpx, qpy, rX, rY) / denom;

        if (t < -EPS || t > 1 + EPS || u < -EPS || u > 1 + EPS) return null;

        return new Point(a.x + t * rX, a.y + t * rY);
    }

    static boolean samePoint(Point p, Point q) {
        return Math.abs(p.x - q.x) < 1e-8 && Math.abs(p.y - q.y) < 1e-8;
    }

