def line_coeffs(x1, y1, x2, y2):
    # Ax + By + C = 0
    A = y2 - y1
    B = x1 - x2
    C = -(A * x1 + B * y1)
    return A, B, C

def intersect(l1, l2):
    A1, B1, C1 = l1
    A2, B2, C2 = l2
    det = A1 * B2 - A2 * B1
    if det == 0:
        return None
    x = Fraction(B1 * C2 - B2 * C1, det)
    y = Fraction(C1 * A2 - C2 * A1, det)
    return (x, y)

